# =====================================================================
# REV3 - UNIT SYSTEM (centralized; convert at boundaries, never scattered)
# Source: Units_Imperial_Metric.xlsx (Units (1).zip)
#   Exact bases (NIST SP 811): 1 in = 25.4 mm, 1 lbf = 4.4482216152605 N,
#   g0 = 9.80665 m/s2, kip = 1000 lbf, ft = 12 in.
# Internal solver set: kN + m throughout, E in kPa, gamma in kN/m3.
# =====================================================================
IN_MM: float = 25.4
LBF_N: float = 4.4482216152605
G0: float = 9.80665
KIP_LBF: float = 1000.0
FT_IN: float = 12.0

FT_M: float = IN_MM * FT_IN / 1000.0              # 0.3048
KSI_MPA: float = LBF_N * KIP_LBF / (IN_MM ** 2)   # 6.89475729316
KIP_KN: float = LBF_N * KIP_LBF / 1000.0          # 4.4482216152605
KIPFT_KNM: float = KIP_KN * FT_M                  # 1.35581794833
KIPFT_KNM_PER_FT: float = KIP_KN / FT_M           # 14.5939029372 (kip/ft -> kN/m)
KCF_KNM3: float = KIP_KN / (FT_M ** 3)            # 157.08746384624
KCF_KGM3: float = KIP_KN * KIP_LBF / (FT_M ** 3) / G0  # 16018.46337396
IN4_MM4: float = IN_MM ** 4                       # 416231.4256
THERM_FACTOR: float = 18.0  # 1e-5/F -> 1e-6/C mantissa (x1.8 for F->C, x10 exponent)

VALID_UNIT_SYSTEMS: tuple[str, ...] = ("Imperial", "Metric")
DEFAULT_UNIT_SYSTEM: str = "Metric"  # model geometry authored in metres
ACTIVE_UNIT_SYSTEMS: tuple[str, ...] = ("Imperial", "Metric")  # Rev3 demonstrates both


class Units:
    """Boundary converter. Solver core stays in kN+m (E in kPa)."""

    @staticmethod
    def from_imperial(E_ksi: float, dens_kcf: float, alpha_1e5F: float) -> dict:
        return {
            "E_kPa": E_ksi * KSI_MPA * 1000.0,
            "gamma_kNm3": dens_kcf * KCF_KNM3,
            "alpha_perC": alpha_1e5F * 1e-5 * 1.8,
        }

    @staticmethod
    def from_metric(E_MPa: float, gamma_kNm3: float, alpha_1e6C: float) -> dict:
        return {
            "E_kPa": E_MPa * 1000.0,
            "gamma_kNm3": gamma_kNm3,
            "alpha_perC": alpha_1e6C * 1e-6,
        }

    @staticmethod
    def length_m_to_ft(L_m: float) -> float:
        return L_m / FT_M

    @staticmethod
    def length_ft_to_m(L_ft: float) -> float:
        return L_ft * FT_M


