DEFAULT_MATERIAL: str = "A36"
MATERIAL_KEYS: tuple[str, ...] = tuple(MATERIALS)


def mat_E_str(key: str, units: str) -> str:
    m = MATERIALS[key]
    if m.get("E_MPa") is None or m.get("E_ksi") is None:
        return "n/a (NDS)*"
    return f'{m["E_MPa"]:.0f} MPa' if units == "Metric" else f'{m["E_ksi"]:.0f} ksi'


def mat_strength_str(key: str, units: str) -> str:
    m = MATERIALS[key]
    cat = m.get("category", "")
    if cat == "Concrete":
        return f"f'c {m['fc_MPa']:.1f} MPa" if units == "Metric" else f"f'c {m['fc_ksi']:.0f} ksi"
    if cat == "Masonry":
        return f"f'm {m['fm_MPa']:.1f} MPa" if units == "Metric" else f"f'm {m['fm_ksi']:.0f} ksi"
    if cat == "Aluminum":
        return f'Fty {m["Fty_MPa"]:.1f} MPa' if units == "Metric" else f'Fty {m["Fty_ksi"]:.0f} ksi'
    if cat == "Wood":
        return "NDS lookup*"
    if "Fy_ksi" in m:
        return f'Fy {m["Fy_MPa"]:.1f} MPa' if units == "Metric" else f'Fy {m["Fy_ksi"]:.0f} ksi'
    return "—"


def mat_gamma_str(key: str, units: str) -> str:
    m = MATERIALS[key]
    if m.get("self_wt") == "Custom":
        return "Custom (blk+grout)*"
    if units == "Metric":
        return f'{m["gamma_kNm3"]} kN/m3'
    return f'{m["gamma_kcf"]} k/ft3'


def mat_flag(key: str) -> str:
    """'*' marker for guarded (non-analyzable) library entries."""
    return "*" if not MATERIALS[key].get("analyzable", True) else ""


