for _b, _f in SEC_ALIAS.items():
    SECTIONS.setdefault(_b, SECTIONS[_f])
del _b, _f
DEFAULT_SECTION: str = "W10X22"
SECTION_KEYS: tuple[str, ...] = tuple(SECTIONS)


def sec_A_str(key: str, units: str) -> str:
    s = SECTIONS[key]
    if units == "Metric":
        return f'A {s.get("A_mm2", "–")} mm2'
    return f'A {s.get("A_in2", "–")} in2'


def sec_Ix_str(key: str, units: str) -> str:
    s = SECTIONS[key]
    if units == "Metric":
        return f'Ix {s.get("Ix_1e6mm4", "–")}e6'
    return f'Ix {s.get("Ix_in4", "–")}'

# Per-group assignment defaults (same everywhere; stored per member so
# future groups can diverge without core change).
GROUP_MATERIAL: dict[str, str] = {
    "Base beam": DEFAULT_MATERIAL,
    "Roof beam": DEFAULT_MATERIAL,
    "Column": DEFAULT_MATERIAL,
}
GROUP_SECTION: dict[str, str] = {
    "Base beam": DEFAULT_SECTION,
    "Roof beam": DEFAULT_SECTION,
    "Column": DEFAULT_SECTION,
}
GROUP_KEYS: tuple[str, ...] = ("Base beam", "Roof beam", "Column")
TARGET_KEYS: tuple[str, ...] = ("All", "Base beam", "Roof beam", "Column")
LAYERS: tuple[str, ...] = ("members", "member_labels", "mat_labels", "sec_labels",
                           "local_axes", "releases", "nodes", "node_labels",
                           "supports", "global_axes")
LAYER_TITLES: dict[str, str] = {"members": "Members", "member_labels": "Member labels",
                                "mat_labels": "Material labels", "sec_labels": "Section labels",
                                "local_axes": "Local axes", "releases": "Releases",
                                "nodes": "Nodes", "node_labels": "Node labels",
                                "supports": "Supports", "global_axes": "Global axes"}


def default_state() -> dict:
    """Interactive + export state. Units = viewer display system."""
    return {
        "units": DEFAULT_UNIT_SYSTEM,  # "Metric" | "Imperial"
        "target": "All",
        "group_mats": dict(GROUP_MATERIAL),
        "group_secs": dict(GROUP_SECTION),
        "layers": {k: True for k in LAYERS},
    }


def target_groups(state: dict) -> list[str]:
    t = state.get("target", "All")
    return list(GROUP_KEYS) if t == "All" else [t]


def validate_unit_system(name: str) -> str:
    if name not in VALID_UNIT_SYSTEMS:
        raise ValueError(f"Unknown unit system {name!r}. Valid: {list(VALID_UNIT_SYSTEMS)}")
    return name


def validate_material(name: str) -> dict:
    if name not in MATERIALS:
        raise ValueError(f"Unknown material {name!r}. Available: {sorted(MATERIALS)}")
    return MATERIALS[name]


def validate_section(name: str) -> dict:
    if name not in SECTIONS:
        raise ValueError(f"Unknown section {name!r}. Available: {sorted(SECTIONS)}")
    return SECTIONS[name]


def validate_model(spans: list[dict]) -> None:
    """Every member must reference a known material + section (per-member)."""
    for m in spans:
        validate_material(m.get("material", ""))
        validate_section(m.get("section", ""))
    for sys in ACTIVE_UNIT_SYSTEMS:
        validate_unit_system(sys)


def validate_state(state: dict) -> None:
    validate_unit_system(state.get("units", ""))
    if state.get("target", "All") not in TARGET_KEYS:
        raise ValueError(f"Unknown target {state.get('target')!r}. Valid: {list(TARGET_KEYS)}")
    for _ly, _on in state.get("layers", {}).items():
        if _ly not in LAYERS:
            raise ValueError(f"Unknown layer {_ly!r}. Valid: {list(LAYERS)}")
        if not isinstance(_on, bool):
            raise ValueError(f"Layer {_ly!r} must be bool, got {_on!r}.")
    for grp, mat in state.get("group_mats", {}).items():
        if grp not in GROUP_KEYS:
            raise ValueError(f"Unknown group {grp!r}.")
        validate_material(mat)
    for grp, sec in state.get("group_secs", {}).items():
        if grp not in GROUP_KEYS:
            raise ValueError(f"Unknown group {grp!r}.")
        validate_section(sec)


def build_joints() -> list[dict]:
    """Eight corner joints. Y is vertical."""
    s = CUBE
    return [
        {"id": 1, "x": 0.0, "y": 0.0, "z": 0.0, "level": "Base"},
        {"id": 2, "x": s, "y": 0.0, "z": 0.0, "level": "Base"},
        {"id": 3, "x": s, "y": 0.0, "z": s, "level": "Base"},
        {"id": 4, "x": 0.0, "y": 0.0, "z": s, "level": "Base"},
        {"id": 5, "x": 0.0, "y": s, "z": 0.0, "level": "Roof"},
        {"id": 6, "x": s, "y": s, "z": 0.0, "level": "Roof"},
        {"id": 7, "x": s, "y": s, "z": s, "level": "Roof"},
        {"id": 8, "x": 0.0, "y": s, "z": s, "level": "Roof"},
    ]


def build_spans(mat_map: dict | None = None, sec_map: dict | None = None) -> list[dict]:
    """M1-M4 base, M5-M8 roof (Mx+Mz released), M9-M12 columns (rigid, beta 90).

    REV3: each member carries its own material + section (per-member
    properties, not globals). Maps default to GROUP_MATERIAL /
    GROUP_SECTION so future models can mix (e.g. concrete column +
    steel beam + timber beam) without core change.
    """
    rel = {"rix": True, "riz": True, "rjx": True, "rjz": True}
    fix = {"rix": False, "riz": False, "rjx": False, "rjz": False}
    raw = [
        {"tag": "M1", "a": 1, "b": 2, "group": "Base beam", "beta": 0.0, **rel},
        {"tag": "M2", "a": 2, "b": 3, "group": "Base beam", "beta": 0.0, **rel},
        {"tag": "M3", "a": 3, "b": 4, "group": "Base beam", "beta": 0.0, **rel},
        {"tag": "M4", "a": 4, "b": 1, "group": "Base beam", "beta": 0.0, **rel},
        {"tag": "M5", "a": 5, "b": 6, "group": "Roof beam", "beta": 0.0, **rel},
        {"tag": "M6", "a": 6, "b": 7, "group": "Roof beam", "beta": 0.0, **rel},
        {"tag": "M7", "a": 7, "b": 8, "group": "Roof beam", "beta": 0.0, **rel},
        {"tag": "M8", "a": 8, "b": 5, "group": "Roof beam", "beta": 0.0, **rel},
        {"tag": "M9", "a": 1, "b": 5, "group": "Column", "beta": 90.0, **fix},
        {"tag": "M10", "a": 2, "b": 6, "group": "Column", "beta": 90.0, **fix},
        {"tag": "M11", "a": 3, "b": 7, "group": "Column", "beta": 90.0, **fix},
        {"tag": "M12", "a": 4, "b": 8, "group": "Column", "beta": 90.0, **fix},
    ]
    for m in raw:
        m["material"] = (mat_map or GROUP_MATERIAL)[m["group"]]
        m["section"] = (sec_map or GROUP_SECTION)[m["group"]]
    return raw


def spans_from_state(state: dict | None = None) -> list[dict]:
    if state is None:
        return build_spans()
    validate_state(state)
    return build_spans(state["group_mats"], state["group_secs"])


