BEARINGS: dict[int, dict] = {
    1: {"label": "PINNED", "fix": (1, 1, 1, 0, 0, 0)},
    2: {"label": "PINNED", "fix": (1, 1, 1, 0, 0, 0)},
    3: {"label": "PINNED", "fix": (1, 1, 1, 0, 0, 0)},
    4: {"label": "PINNED", "fix": (1, 1, 1, 0, 0, 0)},
    5: {"label": "FREE", "fix": (0, 0, 0, 0, 0, 0)},
    6: {"label": "FREE", "fix": (0, 0, 0, 0, 0, 0)},
    7: {"label": "FREE", "fix": (0, 0, 0, 0, 0, 0)},
    8: {"label": "FREE", "fix": (0, 0, 0, 0, 0, 0)},
}

GROUP_STYLE = {
    "Base beam": {"color": "#C46A1B", "width": 2.6},
    "Roof beam": {"color": "#1B6EC4", "width": 2.6},
    "Column": {"color": "#14957F", "width": 2.6},
}

# Small per-quadrant nudges so node tags clear joints/releases.
NODE_OFF: dict[int, tuple[float, float, float]] = {
    1: (-0.55, -0.55, 0.55),
    2: (0.60, -0.55, 0.55),
    3: (0.60, 0.60, 0.55),
    4: (-0.55, 0.60, 0.55),
    5: (-0.55, -0.55, 0.55),
    6: (0.60, -0.55, 0.55),
    7: (0.60, 0.60, 0.55),
    8: (-0.55, 0.60, 0.55),
}

LW_MEMBER = 3.2


def joint_map(joints: list[dict]) -> dict[int, tuple[float, float, float]]:
    return {j["id"]: (j["x"], j["y"], j["z"]) for j in joints}


def span_length(p: tuple[float, float, float], q: tuple[float, float, float]) -> float:
    return math.dist(p, q)


def assign_dof_numbers(joints: list[dict]) -> tuple[dict[int, list[int]], int]:
    """Global DOF numbering. Restrained -> 0, free -> 1..n."""
    numbering: dict[int, list[int]] = {}
    free = 0
    for j in joints:
        fix = BEARINGS[j["id"]]["fix"]
        row: list[int] = []
        for restrained in fix:
            if restrained:
                row.append(0)
            else:
                free += 1
                row.append(free)
        numbering[j["id"]] = row
    return numbering, free


def compute_local_axes(
    p_i: tuple[float, float, float],
    p_j: tuple[float, float, float],
    beta_deg: float = 0.0,
) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, float]:
    """Local axes: lx along I->J, ly/lz rotated by beta about lx.

    up = +Y unless lx near-vertical, then +Z.
    lz = lx x up, ly = lz x lx. Beta rotates ly->lz (deg, right-hand about lx).
    Returns lx, ly, lz, R (rows lx/ly/lz), L.
    """
    pi = np.array(p_i, dtype=float)
    pj = np.array(p_j, dtype=float)
    v = pj - pi
    length = float(np.linalg.norm(v))
    lx = v / length
    up = np.array([0.0, 1.0, 0.0])
    if abs(float(np.dot(lx, up))) > 0.99:
        up = np.array([0.0, 0.0, 1.0])
    lz = np.cross(lx, up)
    lz = lz / np.linalg.norm(lz)
    ly = np.cross(lz, lx)
    ly = ly / np.linalg.norm(ly)
    beta = math.radians(beta_deg)
    if beta != 0.0:
        c, s = math.cos(beta), math.sin(beta)
        ly, lz = c * ly + s * lz, -s * ly + c * lz
    rot = np.vstack([lx, ly, lz])
    return lx, ly, lz, rot, length


def _bearing_glyph(ax, x: float, z: float, ground: float = -1.0, cap: float = -0.15) -> None:
    """Pinned plinth: stem + pyramid + ground plate. Plot axes (X, Z, Y)."""
    ax.plot([x, x], [z, z], [0, cap], color="#1F3864", linewidth=1.6)
    half = 0.55
    corners = [
        (x - half, z - half, ground),
        (x + half, z - half, ground),
        (x + half, z + half, ground),
        (x - half, z + half, ground),
    ]
    apex = (x, z, cap)
    faces = [[apex, corners[k], corners[(k + 1) % 4]] for k in range(4)]
    stone = Poly3DCollection(faces, alpha=0.9, edgecolor="#1F3864", linewidths=0.9)
    stone.set_facecolor("#2E9B8B")
    ax.add_collection3d(stone)
    plate = Poly3DCollection([corners], alpha=0.45, edgecolor="#1F3864", linewidths=1.1)
    plate.set_facecolor("#2E9B8B")
    ax.add_collection3d(plate)


def _title_block(ws, title: str, subtitle: str, ncols: int) -> None:
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=ncols)
    c = ws.cell(row=1, column=1, value=title)
    c.font = Font(name="Calibri", size=13, bold=True, color="FFFFFF")
    c.fill = PatternFill("solid", fgColor=NAVY.lstrip("#"))
    c.alignment = Alignment(horizontal="center", vertical="center")
    ws.row_dimensions[1].height = 26
    ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=ncols)
    s = ws.cell(row=2, column=1, value=subtitle)
    s.font = Font(name="Calibri", size=9, italic=True, color=NAVY.lstrip("#"))
    s.fill = PatternFill("solid", fgColor=LIGHT_BG.lstrip("#"))
    s.alignment = Alignment(horizontal="center", vertical="center")
    ws.row_dimensions[2].height = 18


def _header_row(ws, row: int, headers: list[str]) -> None:
    for col, h in enumerate(headers, start=1):
        c = ws.cell(row=row, column=col, value=h)
        c.font = Font(name="Calibri", size=10, bold=True, color="FFFFFF")
        c.fill = PatternFill("solid", fgColor=TEAL.lstrip("#"))
        c.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
    ws.row_dimensions[row].height = 32


def _body_table(ws, start_row: int, rows: list[list], num_fmt_cols: set[int] | None = None) -> None:
    for r, values in enumerate(rows, start=start_row):
        stripe = (r % 2 == 0)
        for col, val in enumerate(values, start=1):
            c = ws.cell(row=r, column=col, value=val)
            c.font = Font(name="Calibri", size=10, color="1F3864")
            c.border = THIN_BORDER
            c.alignment = Alignment(horizontal="center", vertical="center")
            if stripe:
                c.fill = PatternFill("solid", fgColor=ALT_ROW.lstrip("#"))
            if num_fmt_cols and col in num_fmt_cols and isinstance(val, (int, float)):
                c.number_format = "0.00"


def _fit_columns(ws, widths: list[float]) -> None:
    for i, w in enumerate(widths, start=1):
        ws.column_dimensions[get_column_letter(i)].width = w


def _mat_row(key: str) -> list:
    mat = MATERIALS[key]
    cat = mat.get("category", "")
    if cat == "Concrete":
        s_imp = f'f\'c {mat["fc_ksi"]:.0f} ksi / rebar {mat["rebar_ksi"]:.0f} ksi'
        s_met = f'f\'c {mat["fc_MPa"]:.1f} MPa / rebar {mat["rebar_MPa"]:.1f} MPa'
    elif cat == "Masonry":
        s_imp = f'f\'m {mat["fm_ksi"]:.1f} ksi / rebar {mat["rebar_ksi"]:.0f} ksi'
        s_met = f'f\'m {mat["fm_MPa"]:.1f} MPa / rebar {mat["rebar_MPa"]:.1f} MPa'
    elif cat == "Aluminum":
        s_imp = f'Ftu {mat["Ftu_ksi"]:.0f} / Fty {mat["Fty_ksi"]:.0f} ksi'
        s_met = f'Ftu {mat["Ftu_MPa"]:.1f} / Fty {mat["Fty_MPa"]:.1f} MPa'
    elif cat == "Wood":
        s_imp = s_met = "NDS lookup (no Fy/Fu in library)"
    elif "Fy_ksi" in mat:
        s_imp = f'Fy {mat["Fy_ksi"]:.0f} ksi / Fu {mat["Fu_ksi"]:.0f} ksi'
        s_met = f'Fy {mat["Fy_MPa"]:.1f} MPa / Fu {mat["Fu_MPa"]:.1f} MPa'
    else:
        s_imp = s_met = "—"
    if mat.get("E_ksi") is None:
        e_imp = e_met = "n/a (NDS)"
    else:
        e_imp = f'{mat["E_ksi"]:.0f} ksi (G {mat.get("G_ksi", "—")}, nu {mat["nu"]})'
        e_met = f'{mat["E_MPa"]:.0f} MPa (G {mat.get("G_MPa", "—")})'
    if mat.get("self_wt") == "Custom":
        g_imp, g_met = "Custom (blk+grout)", "Custom (blk+grout)"
    else:
        g_imp = f'{mat["gamma_kcf"]} k/ft3'
        g_met = f'{mat["gamma_kNm3"]} kN/m3 ({mat["mass_kgm3"]:.0f} kg/m3)'
    guard = ("  NOTE: " + mat["guard"]) if mat.get("guard") else ""
    return [key + mat_flag(key), mat["spec"] + guard, e_imp, e_met, g_imp, g_met, s_imp, s_met]


def _sec_val(sec: dict, key: str) -> str:
    v = sec.get(key)
    return "–" if v is None else str(v)


def _sec_row(key: str) -> list:
    sec = SECTIONS[key]
    return [
        key, sec.get("sectype", sec.get("type", "")),
        f'{_sec_val(sec, "W_lbft")} lb/ft', f'{_sec_val(sec, "W_kgm")} kg/m',
        f'A {_sec_val(sec, "A_in2")} in2 (Ix {_sec_val(sec, "Ix_in4")}, Sx {_sec_val(sec, "Sx_in3")}, J {_sec_val(sec, "J_in4")})',
        f'A {_sec_val(sec, "A_mm2")} mm2 (Ix {_sec_val(sec, "Ix_1e6mm4")}e6, Sx {_sec_val(sec, "Sx_1e3mm3")}e3, J {_sec_val(sec, "J_1e3mm4")}e3)',
    ]


def export_workbook(path: Path = XLSX_FILE, state: dict | None = None) -> int:
    if state is None:
        state = default_state()
    validate_state(state)
    joints = build_joints()
    spans = spans_from_state(state)
    validate_model(spans)
    coords = joint_map(joints)
    numbering, n_free = assign_dof_numbers(joints)
    display = state["units"]

    wb = Workbook()

    # ---- Nodes (coords + support + DOF numbers) ----
    ws = wb.active
    ws.title = "Nodes"
    _title_block(ws, "REV. 3 — NODAL DATA", "X lateral, Y vertical (up), Z lateral  •  N1 at origin  •  metres (6.00 m = 19.685 ft)", 12)
    _header_row(ws, 4, ["Node", "X (m)", "Y (m)\nvertical", "Z (m)", "Level", "Support",
                        "Tx #", "Ty #", "Tz #", "Rx #", "Ry #", "Rz #"])
    rows = []
    for j in joints:
        nums = numbering[j["id"]]
        rows.append([j["id"], j["x"], j["y"], j["z"], j["level"],
                     BEARINGS[j["id"]]["label"], *nums])
    _body_table(ws, 5, rows, num_fmt_cols={2, 3, 4})
    _fit_columns(ws, [8, 11, 11, 11, 11, 11, 8, 8, 8, 8, 8, 8])
    ws.freeze_panes = "A5"
    ws.auto_filter.ref = f"A4:L{4 + len(rows)}"

    # ---- Members (incidences + beta + Mx/Mz releases + material + section) ----
    wm = wb.create_sheet("Members")
    _title_block(wm, "MEMBER INCIDENCES + RELEASES + ASSIGNMENTS", f"M1-M4 base, M5-M8 roof pinned Mx+Mz both ends, M9-M12 columns rigid  •  beta 0 deg beams / 90 deg columns  •  Display: {display} (per-member picks below)", 14)
    _header_row(wm, 4, ["Member", "i", "j", "Group", "Length (m)", "Length (ft)", "Beta\n(deg)",
                        "Rel\ni_Mx", "Rel\ni_Mz", "Rel\nj_Mx", "Rel\nj_Mz", "Pinned?",
                        "Material", "Section"])
    mrows = []
    for m in spans:
        length = span_length(coords[m["a"]], coords[m["b"]])
        pinned = "YES" if (m["rix"] or m["riz"] or m["rjx"] or m["rjz"]) else "NO"
        mrows.append([m["tag"], m["a"], m["b"], m["group"], round(length, 2),
                      round(Units.length_m_to_ft(length), 3), m["beta"],
                      int(m["rix"]), int(m["riz"]), int(m["rjx"]), int(m["rjz"]), pinned,
                      m["material"], m["section"]])
    _body_table(wm, 5, mrows, num_fmt_cols={5, 6})
    _fit_columns(wm, [10, 8, 8, 13, 12, 12, 9, 8, 8, 8, 8, 10, 11, 11])
    wm.freeze_panes = "A5"
    wm.auto_filter.ref = f"A4:N{4 + len(mrows)}"
    # Interactive dropdowns: changing these cells + re-running (or Save
    # button) flows through validate_model, so unknown entries are rejected.
    dv_mat = DataValidation(type="list", formula1="Lists_Mat!$A$2:$A$42",
                            allow_blank=False, showErrorMessage=True,
                            errorTitle="Unknown material",
                            error="Pick a material key from the Lists_Mat sheet")
    dv_sec = DataValidation(type="list", formula1="Lists_Sec!$A$2:$A$2500",
                            allow_blank=False, showErrorMessage=True,
                            errorTitle="Unknown section",
                            error="Pick a section label from the Lists_Sec sheet")
    wm.add_data_validation(dv_mat)
    wm.add_data_validation(dv_sec)
    dv_mat.add(f"M5:M{4 + len(mrows)}")
    dv_sec.add(f"N5:N{4 + len(mrows)}")

    # ---- Supports ----
    wq = wb.create_sheet("Supports")
    _title_block(wq, "SUPPORT CONDITIONS", "1 = restrained, 0 = free  •  PINNED = Tx,Ty,Tz fixed", 9)
    _header_row(wq, 4, ["Node", "Condition", "Tx", "Ty", "Tz", "Rx", "Ry", "Rz", "Remark"])
    qrows = []
    for j in joints:
        info = BEARINGS[j["id"]]
        remark = "Pinned base" if info["label"] == "PINNED" else "Free roof joint"
        qrows.append([j["id"], info["label"], *info["fix"], remark])
    _body_table(wq, 5, qrows)
    _fit_columns(wq, [8, 12, 7, 7, 7, 7, 7, 7, 22])
    wq.freeze_panes = "A5"

    # ---- DOFs ----
    wd = wb.create_sheet("DOFs")
    _title_block(wd, "GLOBAL DOF MAP", "0 = restrained by support, >0 = active equation number  •  order Tx,Ty,Tz,Rx,Ry,Rz", 8)
    _header_row(wd, 4, ["Node", "Tx #", "Ty #", "Tz #", "Rx #", "Ry #", "Rz #", "Status"])
    drows = []
    for j in joints:
        nums = numbering[j["id"]]
        status = "Pinned (3 fixed)" if j["id"] <= 4 else "Free (6 active)"
        drows.append([j["id"], *nums, status])
    _body_table(wd, 5, drows)
    foot = 5 + len(drows) + 1
    wd.merge_cells(start_row=foot, start_column=1, end_row=foot, end_column=8)
    note = wd.cell(row=foot, column=1,
                   value=f"Total active DOFs = {n_free} (48 total - 12 restrained at N1-N4). Mx = torsion about local x, Mz = bending about local z.")
    note.font = Font(name="Calibri", size=9, italic=True, color=NAVY.lstrip("#"))
    note.alignment = Alignment(horizontal="center")
    _fit_columns(wd, [8, 9, 9, 9, 9, 9, 9, 26])
    wd.freeze_panes = "A5"

    # ---- LocalAxes ----
    wl = wb.create_sheet("LocalAxes")
    _title_block(wl, "LOCAL AXES (lx ALONG I->J, beta ABOUT lx)", "Unit vectors in global X,Y,Z  •  R rows = lx,ly,lz", 11)
    _header_row(wl, 4, ["Member", "L (m)", "lx_x", "lx_y", "lx_z",
                        "ly_x", "ly_y", "ly_z", "lz_x", "lz_y", "lz_z"])
    lrows = []
    for m in spans:
        lx, ly, lz, _, length = compute_local_axes(coords[m["a"]], coords[m["b"]], m["beta"])
        lrows.append([m["tag"], round(float(length), 4),
                      round(float(lx[0]), 5), round(float(lx[1]), 5), round(float(lx[2]), 5),
                      round(float(ly[0]), 5), round(float(ly[1]), 5), round(float(ly[2]), 5),
                      round(float(lz[0]), 5), round(float(lz[1]), 5), round(float(lz[2]), 5)])
    _body_table(wl, 5, lrows, num_fmt_cols={2})
    _fit_columns(wl, [10, 10, 10, 10, 10, 10, 10, 10, 10, 10, 10])
    wl.freeze_panes = "A5"
    wl.auto_filter.ref = f"A4:K{4 + len(lrows)}"

    # ---- ModelInfo_Units (REV3: centralized unit systems + factors) ----
    wu = wb.create_sheet("ModelInfo_Units")
    _title_block(wu, "UNIT SYSTEMS + CONVERSION FACTORS (EXACT BASES)",
                 "Bases: 1 in = 25.4 mm, 1 lbf = 4.4482216152605 N, g0 = 9.80665 m/s2  •  Internal solver: kN + m, E in kPa", 4)
    _header_row(wu, 4, ["Quantity", "Imperial -> Metric", "Factor (x)", "Note"])
    urows = [
        ["Length", "in -> mm", IN_MM, "exact"],
        ["Length", "ft -> m", FT_M, "12 x 25.4 / 1000"],
        ["Area", "in2 -> mm2", IN_MM ** 2, "25.4^2"],
        ["Inertia", "in4 -> mm4", IN4_MM4, "25.4^4"],
        ["Force", "kip -> kN", KIP_KN, "4.4482216152605"],
        ["Moment", "kip-ft -> kN-m", KIPFT_KNM, "kN x m"],
        ["Stress", "ksi -> MPa", KSI_MPA, "kN/mm2 x 1000"],
        ["Dist load", "kip/ft -> kN/m", KIPFT_KNM_PER_FT, "kN / m"],
        ["Unit weight", "k/ft3 -> kN/m3", KCF_KNM3, "kN / m3"],
        ["Mass density", "k/ft3 -> kg/m3", KCF_KGM3, "N/m3 / g0"],
        ["Thermal", "1e-5/F -> 1e-6/C", THERM_FACTOR, "x1.8 + x10 exponent"],
        ["Cube edge", "6 m -> ft", round(Units.length_m_to_ft(CUBE), 5), f"viewer display: {display}"],
    ]
    _body_table(wu, 5, urows)
    _fit_columns(wu, [16, 22, 20, 38])
    wu.freeze_panes = "A5"
    wu.auto_filter.ref = f"A4:D{4 + len(urows)}"

    # ---- Materials (REV3: library, per-member picks) ----
    wmat = wb.create_sheet("Materials")
    _title_block(wmat, "MATERIAL LIBRARY (41, PER-MEMBER PROPERTY)", "Source: Material/RISA_Materials_Library.xlsx (all 8 tabs)  •  Members!M dropdown fed by Lists_Mat  •  '*' = guarded, see Spec note", 8)
    _header_row(wmat, 4, ["Key", "Spec", "E Imperial", "E Metric", "Density Imperial",
                          "Density Metric", "Strength Imperial", "Strength Metric"])
    _body_table(wmat, 5, [_mat_row(k) for k in MATERIAL_KEYS])
    _fit_columns(wmat, [12, 22, 26, 26, 16, 26, 30, 32])
    wmat.freeze_panes = "A5"
    wmat.auto_filter.ref = f"A4:H{4 + len(MATERIAL_KEYS)}"

    # ---- Sections (REV3: assigned detail + catalog summary) ----
    wsec = wb.create_sheet("Sections")
    _title_block(wsec, "SECTIONS — ASSIGNED (DETAIL) + CATALOG SUMMARY", "Source: aisc-shapes-database-v160-2.xlsx Database v16.0 (2299 shapes)  •  Members!N dropdown fed by Lists_Sec", 6)
    _header_row(wsec, 4, ["Key", "Type", "Weight Imperial", "Weight Metric", "Area Imperial", "Area Metric"])
    assigned = sorted({m["section"] for m in spans})
    secrows = [_sec_row(k) for k in assigned]
    secrows.append(["—", "—", "—", "—", "—", "—"])
    for _t in SEC_TYPES:
        _n = len(SECTIONS_DATA[_t])
        _ex = f'{SECTIONS_DATA[_t][0][0]} … {SECTIONS_DATA[_t][-1][0]}'
        secrows.append([f"TYPE: {_t} ({_n})", "", "", "", _ex, ""])
    _body_table(wsec, 5, secrows)
    _fit_columns(wsec, [22, 10, 16, 16, 44, 44])
    wsec.freeze_panes = "A5"
    wsec.auto_filter.ref = f"A4:F{4 + len(secrows)}"

    # ---- Hidden validation lists (Excel 255-char literal limit) ----
    wlm = wb.create_sheet("Lists_Mat")
    for _i, _k in enumerate(MATERIAL_KEYS, start=1):
        wlm.cell(row=_i + 1, column=1, value=_k)
    wlm.sheet_state = "hidden"
    wls = wb.create_sheet("Lists_Sec")
    _r = 2
    for _lab in SECTION_KEYS:
        wls.cell(row=_r, column=1, value=_lab)
        _r += 1
    wls.sheet_state = "hidden"

    for sheet in wb.worksheets:
        sheet.sheet_properties.pageSetUpPr.fitToPage = True
        sheet.page_setup.orientation = "landscape"
        sheet.page_setup.fitToWidth = 1
        sheet.page_setup.fitToHeight = 0

    wb.save(path)
    print(f"Wrote {path}  sheets={wb.sheetnames}  freeDOF={n_free}")
    return n_free


def draw_frame(ax, state: dict | None = None) -> int:
    """Draw the full 3D frame onto ax. Returns free-DOF count."""
    if state is None:
        state = default_state()
    joints = build_joints()
    spans = spans_from_state(state)
    coords = joint_map(joints)
    _, n_free = assign_dof_numbers(joints)
    Lunit = "ft" if state["units"] == "Imperial" else "m"
    show = state.get("layers", {})

    # Opaque light panes so the viewport never reads as blank.
    for axis in (ax.xaxis, ax.yaxis, ax.zaxis):
        axis.pane.fill = True
        axis.pane.set_facecolor(LIGHT_BG)
        axis.pane.set_edgecolor(GRID_LINE)
    ax.grid(True, linestyle="--", alpha=0.55)

    for m in spans:
        style = GROUP_STYLE[m["group"]]
        xa, ya, za = coords[m["a"]]
        xb, yb, zb = coords[m["b"]]
        if show.get("members", True):
            ax.plot([xa, xb], [za, zb], [ya, yb],
                    color=style["color"], linewidth=LW_MEMBER, zorder=3)
        qx, qz, qy = (xa + xb) / 2, (za + zb) / 2, (ya + yb) / 2

        # Local axes stay at the true midpoint ...
        lx, ly, lz, _, _ = compute_local_axes((xa, ya, za), (xb, yb, zb), m["beta"])
        if show.get("local_axes", True):
            ax.quiver(qx, qz, qy, float(lx[0]), float(lx[2]), float(lx[1]),
                      length=0.75, normalize=True, color="#D61F1F", linewidth=1.4, zorder=4)
            ax.quiver(qx, qz, qy, float(ly[0]), float(ly[2]), float(ly[1]),
                      length=0.45, normalize=True, color="#1FA31F", linewidth=1.1, zorder=4)
            ax.quiver(qx, qz, qy, float(lz[0]), float(lz[2]), float(lz[1]),
                      length=0.45, normalize=True, color="#1F4FD6", linewidth=1.1, zorder=4)

        # ... member label floats just above it, never underneath.
        if m["group"] == "Column":
            tx, tz, ty = qx + 0.60, qz, qy + 0.30
            if m["tag"] in ("M10", "M12"):
                ty -= 0.70  # clear N2 / N6 DOF tags in this view
        else:
            tx, tz, ty = qx, qz, qy + 0.55
        if show.get("member_labels", True):
            ax.text(tx, tz, ty, m["tag"], fontsize=7.5, weight="bold", zorder=8,
                    color=style["color"], ha="center", va="center",
                    bbox={"boxstyle": "round,pad=0.30", "fc": "white",
                          "ec": style["color"], "alpha": 1.0})
        if show.get("mat_labels", True):
            ax.text(tx, tz, ty - 0.42, m["material"], fontsize=5.5, zorder=8,
                    color="#5B6B7A", ha="center", va="center",
                    bbox={"boxstyle": "round,pad=0.22", "fc": "white",
                          "ec": "#5B6B7A", "alpha": 1.0})
        if show.get("sec_labels", True):
            ax.text(tx, tz, ty - 0.78, m["section"], fontsize=5.5, zorder=8,
                    color="#5B6B7A", ha="center", va="center",
                    bbox={"boxstyle": "round,pad=0.22", "fc": "white",
                          "ec": "#5B6B7A", "alpha": 1.0})

        # Mx/Mz release circles tucked just inside each released end.
        lx_end, _, _, _, _ = compute_local_axes((xa, ya, za), (xb, yb, zb), m["beta"])
        off = 0.32
        if show.get("releases", True) and (m["rix"] or m["riz"]):
            ax.scatter([xa + float(lx_end[0]) * off],
                       [za + float(lx_end[2]) * off],
                       [ya + float(lx_end[1]) * off],
                       s=62, facecolors="white", edgecolors="black",
                       marker="o", depthshade=False, zorder=7, linewidths=1.2)
        if show.get("releases", True) and (m["rjx"] or m["rjz"]):
            ax.scatter([xb - float(lx_end[0]) * off],
                       [zb - float(lx_end[2]) * off],
                       [yb - float(lx_end[1]) * off],
                       s=62, facecolors="white", edgecolors="black",
                       marker="o", depthshade=False, zorder=7, linewidths=1.2)

    xs = [j["x"] for j in joints]
    zs = [j["z"] for j in joints]
    ys = [j["y"] for j in joints]
    if show.get("nodes", True):
        ax.scatter(xs, zs, ys, c="#B00020", s=90, edgecolors="white",
                   linewidths=1.5, depthshade=True, zorder=6)
    if show.get("node_labels", True):
        for j in joints:
            start = (j["id"] - 1) * 6 + 1
            dx, dz, dy = NODE_OFF[j["id"]]
            ax.text(j["x"] + dx, j["z"] + dz, j["y"] + dy,
                    f'N{j["id"]} DOF ({start}-{start + 5})',
                    fontsize=6.5, color=NAVY, weight="bold",
                    ha="center", va="center", zorder=20,
                    bbox={"boxstyle": "round,pad=0.30", "fc": "white",
                          "ec": NAVY, "alpha": 1.0})

    if show.get("supports", True):
        for j in joints:
            if BEARINGS[j["id"]]["label"] == "PINNED":
                _bearing_glyph(ax, j["x"], j["z"])
                ax.text(j["x"], j["z"], -1.60, "PINNED", fontsize=7,
                        color="#0E6B7A", weight="bold", ha="center", va="top", zorder=9,
                        bbox={"boxstyle": "round,pad=0.25", "fc": "white",
                              "ec": "#0E6B7A", "alpha": 1.0})

    ox, oz, oy = -2.4, -2.4, -1.2
    if show.get("global_axes", True):
        ax.quiver(ox, oz, oy, 1, 0, 0, length=1.7, normalize=True, color="#C0392B", linewidth=2.5)
        ax.quiver(ox, oz, oy, 0, 1, 0, length=1.7, normalize=True, color="#7D7D7D", linewidth=2.5)
        ax.quiver(ox, oz, oy, 0, 0, 1, length=1.7, normalize=True, color="#0E6B7A", linewidth=2.5)
        ax.text(ox + 2.0, oz, oy, "X", color="#C0392B", fontsize=11, weight="bold",
                ha="center", va="center",
                bbox={"boxstyle": "round,pad=0.2", "fc": "white", "ec": "#C0392B", "alpha": 1.0})
        ax.text(ox, oz + 2.0, oy, "Z", color="#7D7D7D", fontsize=11, weight="bold",
                ha="center", va="center",
                bbox={"boxstyle": "round,pad=0.2", "fc": "white", "ec": "#7D7D7D", "alpha": 1.0})
        ax.text(ox, oz, oy + 1.9, "Y", color="#0E6B7A", fontsize=11, weight="bold",
                ha="center", va="center",
                bbox={"boxstyle": "round,pad=0.2", "fc": "white", "ec": "#0E6B7A", "alpha": 1.0})

    ax.set_xlabel(f"X — lateral ({Lunit})", fontsize=10, color=NAVY)
    ax.set_ylabel(f"Z — lateral ({Lunit})", fontsize=10, color=NAVY)
    ax.set_zlabel(f"Y — vertical ({Lunit})", fontsize=10, color=NAVY)
    ax.set_title(f"3D FRAME — 6 m CUBE (Y UP)  •  {state['units']}", fontsize=12, weight="bold", color=NAVY, pad=12)
    ax.set_xlim(-2.6, 8.6)
    ax.set_ylim(-2.6, 8.6)
    ax.set_zlim(-2.4, 8.8)
    try:
        ax.set_box_aspect((1, 1, 1))
    except Exception:
        pass
    ax.view_init(elev=22, azim=-58)
    return n_free


def _style_table(tbl, nrows: int, fontsize: float = 6.8) -> None:
    """Navy header, thin grid, alternating row shading."""
    for (r, c), cell in tbl.get_celld().items():
        cell.set_edgecolor(GRID_LINE)
        cell.set_linewidth(0.6)
        cell.PAD = 0.025
        if r == 0:
            cell.set_facecolor(NAVY)
            cell.get_text().set_color("white")
            cell.get_text().set_weight("bold")
        else:
            cell.set_facecolor(ALT_ROW if r % 2 == 0 else "white")
            cell.get_text().set_color(NAVY)
        cell.get_text().set_fontsize(fontsize)


def _add_section_table(ax_info, y_top: float, title: str,
                       col_labels: list[str], data: list[list],
                       col_widths: list[float] | None = None,
                       fontsize: float = 6.2) -> float:
    """Draw a titled table; returns the y (axes fraction) below it."""
    ax_info.text(0.015, y_top, title, transform=ax_info.transAxes,
                 fontsize=7.5, weight="bold", color="white", va="top", ha="left",
                 bbox={"boxstyle": "round,pad=0.30", "fc": TEAL, "ec": "none"})
    nrows = len(data) + 1
    row_h = 0.016
    height = nrows * row_h
    gap_title = 0.030
    y0 = y_top - gap_title - height
    tbl = ax_info.table(cellText=[[str(v) for v in row] for row in data],
                        colLabels=col_labels, loc="upper left",
                        bbox=[0.015, y0, 0.97, height])
    tbl.auto_set_font_size(False)
    _style_table(tbl, nrows, fontsize)
    if col_widths:
        for idx, w in enumerate(col_widths):
            for r in range(nrows):
                tbl[(r, idx)].set_width(w)
    return y0 - 0.012


def draw_panel(ax_info, state: dict | None = None) -> int:
    """Right-side engineering data sheet built live from the model + state."""
    if state is None:
        state = default_state()
    joints = build_joints()
    spans = spans_from_state(state)
    coords = joint_map(joints)
    numbering, n_free = assign_dof_numbers(joints)
    units = state["units"]
    Lunit = "ft" if units == "Imperial" else "m"
    Lval = "19.685 ft" if units == "Imperial" else "6.00 m"

    ax_info.axis("off")
    ax_info.set_xlim(0, 1)
    ax_info.set_ylim(0, 1)
    ax_info.set_facecolor("white")
    for spine in ax_info.spines.values():
        spine.set_visible(True)
        spine.set_edgecolor(NAVY)
        spine.set_linewidth(1.4)

    ax_info.text(0.5, 0.985, "REV. 3 — MODEL DATA", ha="center", va="top",
                 fontsize=13, weight="bold", color="white",
                 bbox={"boxstyle": "square,pad=0.50", "fc": NAVY, "ec": "none"})
    ax_info.text(0.5, 0.946, f"6 m cube  •  X/Z lateral, Y vertical  •  Display: {units}",
                 ha="center", va="top", fontsize=7.5, style="italic", color=NAVY)

    y = 0.918
    y = _add_section_table(ax_info, y, "01 · GEOMETRY — JOINTS",
                           ["Node", "X", "Y↑", "Z"],
                           [[j["id"], f'{j["x"]:.1f}', f'{j["y"]:.1f}', f'{j["z"]:.1f}']
                            for j in joints])
    y = _add_section_table(ax_info, y, f"02 · GEOMETRY — MEMBERS (L = {Lval})",
                           ["Group", "Members", "Ends"],
                           [["Base beam", "M1–M4", "1→2→3→4→1"],
                            ["Roof beam", "M5–M8", "5→6→7→8→5"],
                            ["Column", "M9–M12", "1→5 2→6 3→7 4→8"]])
    y = _add_section_table(ax_info, y, "03 · GLOBAL AXES",
                           ["Axis", "Role", "Colour"],
                           [["X", "lateral", "red"],
                            ["Y", "vertical ↑", "teal"],
                            ["Z", "lateral", "gray"]])
    y = _add_section_table(ax_info, y, "04 · SUPPORTS (1 = restrained)",
                           ["Nodes", "Type", "Tx Ty Tz · Rx Ry Rz"],
                           [["N1–N4", "PINNED", "1 1 1 · 0 0 0"],
                            ["N5–N8", "FREE", "0 0 0 · 0 0 0"]])
    y = _add_section_table(ax_info, y, "05 · NODAL DOF — display / analysis",
                           ["Node", "Display", "Analysis Tx–Rz"],
                           [[f'N{j["id"]}',
                             f'{(j["id"] - 1) * 6 + 1}-{(j["id"]) * 6}',
                             ",".join(str(d) for d in numbering[j["id"]])]
                            for j in joints],
                           fontsize=6.2)
    y = _add_section_table(ax_info, y, "06 · MEMBER END RELEASES + BETA",
                           ["Members", "Mx Mz i/j", "β"],
                           [["M1–M8 beams", "1/1 · 1/1 YES", "0.0°"],
                            ["M9–M12 cols", "0/0 · 0/0 NO", "90.0°"]])
    # Representative local-x samples keep the sheet to one page;
    # the full 12×9 matrix follows lx=I→J, lz=lx×up, ly=lz×lx.
    lx_demo = []
    for tag in ("M1", "M2", "M9"):
        m = next(s for s in spans if s["tag"] == tag)
        lx, _, _, _, _ = compute_local_axes(coords[m["a"]], coords[m["b"]], m["beta"])
        lx_demo.append([tag, f'{m["a"]}→{m["b"]}',
                        f'({lx[0]:+.0f},{lx[1]:+.0f},{lx[2]:+.0f})'])
    y = _add_section_table(ax_info, y, "07 · LOCAL AXES (lx = I→J)",
                           ["Mem", "I→J", "lx (X,Y,Z)"],
                           lx_demo,
                           fontsize=5.8)
    y = _add_section_table(ax_info, y, "08 · MATERIALS + SECTIONS (per-member)",
                           ["Group", "Material", "E", "Section", "A"],
                           [[grp,
                             state["group_mats"][grp],
                             mat_E_str(state["group_mats"][grp], units),
                             state["group_secs"][grp],
                             sec_A_str(state["group_secs"][grp], units)]
                            for grp in GROUP_KEYS],
                           fontsize=5.8)

    ax_info.text(0.015, y - 0.002,
                 "lx=I→J · lz=lx×up · ly=lz×lx · red=lx grn=ly blu=lz",
                 transform=ax_info.transAxes, fontsize=5.8, style="italic",
                 color=NAVY, va="top", ha="left")
    ax_info.text(0.015, y - 0.014,
                 "○=Mx/Mz · ▲=PINNED · full: xlsx LocalAxes",
                 transform=ax_info.transAxes, fontsize=5.8, style="italic",
                 color=NAVY, va="top", ha="left")
    _ = span_length
    return n_free


def footer_str(state: dict, n_free: int) -> str:
    mats = ",".join(sorted(set(state["group_mats"].values())))
    secs = ",".join(sorted(set(state["group_secs"].values())))
    edge = "19.685ft" if state["units"] == "Imperial" else "6m"
    return (f"Display: {state['units']} ({edge})  •  {mats} + {secs}  •  "
            f"src: REV3.py  •  {n_free} free DOF")


def main() -> None:
    state = default_state()
    validate_state(state)
    validate_model(spans_from_state(state))
    n_free = export_workbook(state=state)
    plt.style.use("seaborn-v0_8-whitegrid")
    from matplotlib.figure import Figure
    fig = Figure(figsize=(18, 9.5))
    gs = fig.add_gridspec(1, 2, width_ratios=[3.0, 1.0], wspace=0.06)
    ax3d = fig.add_subplot(gs[0, 0], projection="3d")
    ax_info = fig.add_subplot(gs[0, 1])

    n_free = draw_frame(ax3d, state)
    draw_panel(ax_info, state)

    fig.suptitle("6m x 6m x 6m Cube - Structural Model, Rev. 3 (switchable units / materials / sections)",
                 fontsize=15, weight="bold", color=NAVY, y=0.98)
    fig.text(0.5, 0.935,
             "Pinned supports at nodes 1-4, global and local axes, "
             "beta angles, MZ end releases — use the controls on the left to change values",
             ha="center", va="top", fontsize=9.5, style="italic", color=NAVY)
    legend_handles = [
        Line2D([0], [0], color="#C46A1B", lw=3.5, label="Base beam M1–M4"),
        Line2D([0], [0], color="#1B6EC4", lw=3.5, label="Roof beam M5–M8"),
        Line2D([0], [0], color="#14957F", lw=3.5, label="Column M9–M12"),
        Line2D([0], [0], marker="o", color="w", markerfacecolor="white",
               markeredgecolor="black", markersize=8, label="Mx/Mz pinned"),
        Line2D([0], [0], marker="^", color="w", markerfacecolor="#2E9B8B",
               markeredgecolor=NAVY, markersize=10, label="PINNED"),
    ]
    fig.legend(handles=legend_handles, loc="lower center", ncol=5,
               fontsize=8.5, frameon=True, facecolor="white", edgecolor=GRID_LINE,
               bbox_to_anchor=(0.375, 0.015))
    foot = fig.text(0.86, 0.01, footer_str(state, n_free),
                    ha="center", va="bottom", fontsize=7.5, style="italic", color=NAVY)
    fig.subplots_adjust(left=0.03, right=0.985, top=0.86, bottom=0.10, wspace=0.06)

    def redraw() -> None:
        validate_state(state)
        ax3d.cla()
        ax_info.cla()
        free = draw_frame(ax3d, state)
        draw_panel(ax_info, state)
        foot.set_text(footer_str(state, free))
        fig.canvas.draw_idle()

    def on_units(label: str) -> None:
        state["units"] = validate_unit_system(label)
        redraw()

    def on_target(label: str) -> None:
        if label not in TARGET_KEYS:
            raise ValueError(f"Unknown target {label!r}.")
        state["target"] = label

    def on_material(label: str) -> None:
        validate_material(label)
        for grp in target_groups(state):
            state["group_mats"][grp] = label
        redraw()

    def on_section(label: str) -> None:
        validate_section(label)
        for grp in target_groups(state):
            state["group_secs"][grp] = label
        redraw()

    def on_save() -> None:
        for grp in GROUP_KEYS:
            _mk = state["group_mats"][grp]
            if not MATERIALS[_mk].get("analyzable", True):
                print(f"WARNING: {grp} uses guarded material {_mk}: {MATERIALS[_mk].get('guard', '')}")
        free = export_workbook(state=state)
        fig.savefig(PNG_FILE, dpi=220)
        foot.set_text(footer_str(state, free))
        try:
            fig.canvas.draw_idle()
        except Exception:
            pass
        print(f"Saved {XLSX_FILE.name} + {PNG_FILE.name}  "
              f"units={state['units']} mats={state['group_mats']} secs={state['group_secs']}")

    # ---- Single-window app: controls docked in a left sidebar ----
    # One Tk window: narrow control frame on the left (4 readonly
    # Comboboxes + Save), embedded matplotlib canvas on the right.
    # Skipped on non-interactive backends (Agg) so headless runs /
    # tests keep working with zero GUI.
    try:
        import matplotlib as _mpl
        _interactive = _mpl.get_backend().lower() != "agg"
    except Exception:
        _interactive = False
    if not _interactive:
        fig.savefig(PNG_FILE, dpi=220)
        print(f"Saved UI to {PNG_FILE}")
        return

    try:
        import tkinter as _tk
        from tkinter import ttk as _ttk

        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg

        _root = _tk.Tk()
        _root.title("REV3 — 6m Cube")
        _side = _ttk.Frame(_root, padding=8)
        _side.pack(side="left", fill="y")
        _view = _ttk.Frame(_root)
        _view.pack(side="right", fill="both", expand=True)

        def _row(label: str, values: list[str], current: str, width: int = 18):
            _ttk.Label(_side, text=label).pack(anchor="w", pady=(8, 0))
            box = _ttk.Combobox(_side, values=values, state="readonly", width=width)
            box.set(current)
            box.pack(anchor="w", pady=(0, 2))
            return box

        def _sizes_for(sectype: str) -> list[str]:
            if sectype == "2L":
                return sorted(SEC_ALIAS)
            return [lab for lab, _, _ in SECTIONS_DATA[sectype]]

        def _resolve_sec(label: str) -> str:
            return SEC_ALIAS.get(label, label)

        _cb_units = _row("Units", list(VALID_UNIT_SYSTEMS), state["units"])
        _cb_target = _row("Apply to", list(TARGET_KEYS), state["target"])
        _cb_mat = _row("Material (41)", list(MATERIAL_KEYS), state["group_mats"]["Base beam"], 22)
        _cb_type = _row("Section type", list(SEC_TYPES), "W")
        _cb_sec = _row("Size", _sizes_for("W"), state["group_secs"]["Base beam"], 22)
        _cb_units.bind("<<ComboboxSelected>>", lambda _e: on_units(_cb_units.get()))
        _cb_target.bind("<<ComboboxSelected>>", lambda _e: on_target(_cb_target.get()))
        _cb_mat.bind("<<ComboboxSelected>>", lambda _e: on_material(_cb_mat.get()))

        def _on_type(_e=None) -> None:
            sizes = _sizes_for(_cb_type.get())
            _cb_sec["values"] = sizes
            _cb_sec.set(sizes[0])
            on_section(_resolve_sec(sizes[0]))

        def _on_size(_e=None) -> None:
            on_section(_resolve_sec(_cb_sec.get()))

        _cb_type.bind("<<ComboboxSelected>>", _on_type)
        _cb_sec.bind("<<ComboboxSelected>>", _on_size)

        _ttk.Label(_side, text="Layers").pack(anchor="w", pady=(10, 0))
        _layer_vars: dict[str, object] = {}

        def _on_layer(key: str) -> None:
            state["layers"][key] = bool(_layer_vars[key].get())
            validate_state(state)
            redraw()

        for _ly in LAYERS:
            _var = _tk.BooleanVar(value=state["layers"][_ly])
            _layer_vars[_ly] = _var
            _ttk.Checkbutton(_side, text=LAYER_TITLES[_ly], variable=_var,
                             command=lambda k=_ly: _on_layer(k)).pack(anchor="w")
        _ttk.Button(_side, text="Save xlsx+png", command=on_save).pack(
            fill="x", pady=(8, 0))

        _canvas = FigureCanvasTkAgg(fig, master=_view)
        _canvas.draw()
        _canvas.get_tk_widget().pack(side="top", fill="both", expand=True)

        _root.protocol("WM_DELETE_WINDOW", _root.destroy)
        _root.mainloop()
    except Exception as exc:
        print(f"(embedded UI skipped: {exc})")
        fig.savefig(PNG_FILE, dpi=220)
        print(f"Saved UI to {PNG_FILE}")


if __name__ == "__main__":
    main()
